			col = mix(col, steel * (1.0 - lap * 0.6), back);
			gMetal = back * (1.0 - lap * 0.7); gRough = mix(gRough, 0.38 + 0.12 * gN(uv * 90.0), back); gSpec = mix(gSpec, 1.0, back);
			gBump += back * lame * 0.0004 * gFade(0.006, px);
